```js
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

let controller;

async function search(query) {
  controller?.abort(); // cancel the in-flight request so stale results can't overwrite newer ones
  if (!query.trim()) return renderResults([]);

  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    renderResults(await res.json());
  } catch (err) {
    if (err.name !== 'AbortError') throw err;
  }
}

input.addEventListener('input', debounce((e) => search(e.target.value), 300));
```

## React

```jsx
import { useEffect, useState } from 'react';

function useDebouncedValue(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}

export function SearchInput() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const debouncedQuery = useDebouncedValue(query, 300);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setResults([]);
      return;
    }
    const controller = new AbortController();
    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => res.json())
      .then(setResults)
      .catch((err) => {
        if (err.name !== 'AbortError') throw err;
      });
    return () => controller.abort();
  }, [debouncedQuery]);

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search…" />
      <ul>{results.map((r) => <li key={r.id}>{r.name}</li>)}</ul>
    </>
  );
}
```

## What to adapt

- **Placeholders:** `/api/search`, `renderResults`, and the `r.id` / `r.name` fields are stand-ins for your endpoint and result shape.
- **Delay:** 300 ms is a common default; 150–250 ms feels snappier and 400–500 ms suits an expensive endpoint.
- **Abort:** debounce alone doesn't stop a slow earlier response from landing after a newer one, which is why both versions also cancel the in-flight request.
- **React input state:** the input stays bound to `query`, so typing remains instant and only the API call waits.

